from __future__ import annotations

import sys

import torch
import helion
import helion.language as hl

from loom import LoomKernel
from loom.loom_utils.kernel_size import resolve_kernel_shape_args
from helion_mlir.custom_op import broadcast  # noqa: F401  (registers the op)


def _k6_gemm(lhs: torch.Tensor, in0: torch.Tensor, in1: torch.Tensor) -> tuple[torch.Tensor, ...]:
    t, k = lhs.size()
    n = k
    out_mul_71 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    for tile_t, tile_n in hl.tile([t, n]):
        ss = hl.zeros([tile_t, 32], dtype=torch.float16)
        for tile_k in hl.tile(k):
            xt = lhs[tile_t, tile_k]
            half = hl.full([tile_t, tile_k], 0.5, dtype=torch.float16)
            sq = xt * (xt * half)
            ones = hl.full([tile_k, 32], 1.0, dtype=torch.float16)
            ss = hl.dot(sq, ones, acc=ss)
        ss_col = torch.amax(ss, -1, keepdim=True)
        c_1 = hl.full([tile_t, 1], 2.0, dtype=torch.float16)
        sumsq = ss_col * c_1
        c_3 = hl.full([tile_t, 1], 0.001953125, dtype=torch.float16)
        mul_65__col_2 = sumsq * c_3
        c_5 = hl.full([tile_t, 1], 0.01, dtype=torch.float16)
        c_6 = hl.full([tile_t, 1], 0.001, dtype=torch.float16)
        c_7 = c_5 * c_6
        add_66__col_4 = mul_65__col_2 + c_7
        c_9 = hl.full([tile_t, 1], -0.5, dtype=torch.float16)
        powf_67__col_8 = torch.pow(add_66__col_4, c_9)
        broadcast_68_10 = broadcast(powf_67__col_8, 1, [powf_67__col_8.size(0), tile_n])
        ld_12 = in0[tile_t, tile_n]
        mul_69_11 = ld_12 * broadcast_68_10
        ld_14 = in1[tile_t, tile_n]
        mul_71_13 = mul_69_11 * ld_14
        out_mul_71[tile_t, tile_n] = mul_71_13
    return out_mul_71,


class K6Gemm(LoomKernel):
    """Loom entry point for kernel ``k6_gemm``."""

    kernel_name = "k6_gemm"
    assume_divisible: bool = True

    ARG_SHAPES = [('lhs', [512, 512]), ('in0', [512, 512]), ('in1', [512, 512])]
    CONSTEXPRS = []
    TILES = {'tile_t': 32, 'tile_n': 128, 'tile_k': 256}

    kernel = helion.kernel(
        static_shapes=False,
        autotune_config_overrides={
            "range_unroll_factors": [0, 0],
            "range_num_stages": [0, 0],
        },
    )(_k6_gemm)

    def __init__(self, shape: dict[str, int] | None = None) -> None:
        if shape:
            raise SystemExit("generated kernels have fixed shapes; regenerate with torch-helion instead")

    @classmethod
    def bind_args(cls) -> tuple:
        args = [torch.empty(shape, dtype=torch.float16) for _, shape in cls.ARG_SHAPES]
        return tuple(args + [v for _, v in cls.CONSTEXPRS])


if __name__ == "__main__":
    try:
        shape, normalized_argv = resolve_kernel_shape_args(sys.argv)
    except ValueError as exc:
        raise SystemExit(str(exc)) from exc

    sys.argv = normalized_argv
    K6Gemm(shape).run()
